pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;
    function setUp() public { c = new MyContract(); }

    function testFuzz_property(address receiver, uint256 amount) public {
        vm.assume(amount > 0);
        vm.assume(receiver != address(this));

        vm.deal(address(c), amount);

        uint256 beforeReceiver = receiver.balance;
        uint256 beforeContract = address(c).balance;

        c.sendTo(receiver, amount);

        assertTrue(receiver.balance == beforeReceiver + amount);
    }
}
